@Component({
  selector: 'app-contactos',
  standalone: true,
  templateUrl: './contactos.component.html',
  styleUrl: './contactos.component.css'
})
export class ContactosComponent {}
<div class="contactos-container">
  <h1>Contactos</h1>
  <p>Gestiona tus contactos</p>
</div>
